  -- Autogenerated filler questions using CTE for guaranteed atomicity
  WITH autogenerated_questions AS (
    INSERT INTO public.public_quiz_questions (quiz_id, question_text, order_index, time_limit_seconds)
    SELECT 
      quiz,
      format('General Knowledge Question %s: Choose the best answer.', i),
      i,
      20
    FROM generate_series(order_idx + 1, target_total) AS i
    RETURNING id, order_index
  ),
  expanded_options AS (
    SELECT 
      aq.id,
      aq.order_index,
      opt_num,
      format('Option %s for Q%s', 
        CASE WHEN opt_num = 1 THEN 'A' WHEN opt_num = 2 THEN 'B' WHEN opt_num = 3 THEN 'C' ELSE 'D' END,
        aq.order_index
      ) AS opt_text,
      ((aq.order_index % 4) + 1) = opt_num AS is_correct,
      opt_num
    FROM autogenerated_questions aq
    CROSS JOIN generate_series(1, 4) AS opt_num
  )
  INSERT INTO public.public_quiz_options (question_id, option_text, is_correct, order_index)
  SELECT id, opt_text, is_correct, opt_num FROM expanded_options;

  -- Update quiz total_questions
  UPDATE public.public_quizzes SET total_questions = target_total WHERE id = quiz;

END
$$ LANGUAGE plpgsql;

COMMIT;
